import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Verification and replay prevention","description":"","frontmatter":{},"headers":[],"relativePath":"verification.md","filePath":"verification.md"}'),n={name:"verification.md"};function i(c,e,s,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="verification-and-replay-prevention" tabindex="-1">Verification and replay prevention <a class="header-anchor" href="#verification-and-replay-prevention" aria-label="Permalink to &quot;Verification and replay prevention&quot;">​</a></h1><h2 id="check-user-input" tabindex="-1">Check user input <a class="header-anchor" href="#check-user-input" aria-label="Permalink to &quot;Check user input&quot;">​</a></h2><p>Pass a string containing exactly the configured number of ASCII decimal digits. Invalid token shapes return <code>false</code> for TOTP and <code>null</code> for HOTP. Invalid keys or configuration throw an error.</p><p>Verification compares token bytes with Node&#39;s <code>timingSafeEqual</code>. It checks the full configured window even when a match is found. This is not a guarantee that the entire request handler has constant timing.</p><h2 id="keep-windows-small" tabindex="-1">Keep windows small <a class="header-anchor" href="#keep-windows-small" aria-label="Permalink to &quot;Keep windows small&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>Default</th><th>Counters checked</th></tr></thead><tbody><tr><td><code>verifyTOTP</code></td><td><code>window: 1</code></td><td>Previous, current, and next</td></tr><tr><td><code>verifyHOTP</code></td><td><code>window: 10</code></td><td>Current and next 10</td></tr></tbody></table><p>Windows must be integers from 0 to 1000. The upper limit prevents unbounded verification loops; typical deployments use much smaller values. Each accepted counter increases the number of valid codes at a given moment.</p><h2 id="prevent-reuse" tabindex="-1">Prevent reuse <a class="header-anchor" href="#prevent-reuse" aria-label="Permalink to &quot;Prevent reuse&quot;">​</a></h2><p><code>verifyTOTP</code> is stateless and can accept the same valid code again during its time window. Track acceptance in your application, using an atomic transaction or uniqueness constraint. For a single-counter workflow, use <code>window: 0</code> and record the accepted user/counter pair. More complex drift handling needs an application policy that accounts for all accepted counters.</p><p>For HOTP, atomically persist <code>newCounter</code> with the successful operation. Concurrent requests must not both accept the same stored counter.</p><h2 id="protect-the-login-flow" tabindex="-1">Protect the login flow <a class="header-anchor" href="#protect-the-login-flow" aria-label="Permalink to &quot;Protect the login flow&quot;">​</a></h2><p>Keep secrets out of logs, give each user a separate random secret, limit attempts, and keep server clocks synchronized. The library does not manage enrollment sessions, backup codes, rate limits, secret storage, or database transactions.</p><p>See <a href="https://www.rfc-editor.org/rfc/rfc6238.html" target="_blank" rel="noreferrer">RFC 6238</a> for the protocol&#39;s verification requirements and <a href="/authenticators.html">authenticator setup</a> for enrollment.</p>',13)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
